examples.template:
Menu {
    Button({{items.0.label}}, systemImage: "pencil") {}
    Button({{items.1.label}}) {}
        .keyboardShortcut("d", modifiers: .command)
    Divider()
    Button({{items.2.label}}, systemImage: "trash", role: .destructive) {}
} label: {
    HStack(spacing: theme.spacing.space1_5) {
        Text({{label}})
        MonarchIcon(systemName: "chevron.down", size: .sm)
    }
}
.buttonStyle(.monarch())

